"use client";

import { type ToggleGroupProps, ToggleGroup as ToggleGroupRoot } from "./toggle-group";
import { ToggleGroupItem, type ToggleGroupItemProps } from "./toggle-group-item";

const ToggleGroup = Object.assign(ToggleGroupRoot, {
  Item: ToggleGroupItem,
});

export { ToggleGroup, type ToggleGroupProps };
export { ToggleGroupItem, type ToggleGroupItemProps };
export { type CreateToggleGroupReturn, createToggleGroup } from "./create-toggle-group";

"use client";

import {
  Children,
  isValidElement,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  type Ref,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { useControllableState } from "@/hooks/use-controllable-state";
import { useFloatingIndicator } from "@/hooks/use-floating-indicator";
import { useFormReset } from "@/hooks/use-form-reset";
import { useNavigation } from "@/hooks/use-navigation";
import {
  type SegmentedSize,
  type SegmentedVariant,
  segmentedContainerVariants,
  segmentedPillIndicatorClass,
  segmentedUnderlineIndicatorClass,
} from "@/lib/segmented-variants";
import {
  getEnabledSelectableCollectionItems,
  isSeedElementSkipped,
  useSelectableCollection,
} from "@/lib/selectable-collection";
import { cn } from "@/lib/utils";
import { ToggleGroupContext, type ToggleGroupSelectionMode } from "./toggle-group-context";
import { ToggleGroupItem } from "./toggle-group-item";

// The inactive selection mode still feeds its useControllableState every render. A fresh []
// there would change identity each time and invalidate the context memo every item reads.
const EMPTY_VALUES: readonly string[] = [];

/** Props for toggle group in single-selection mode. */
interface ToggleGroupSingleProps {
  /**
   * Switches between radio-style single selection and pressed-button-style multiple selection.
   * Switches value/onChange/defaultValue from string|null to readonly string[].
   */
  selectionMode?: "single" | undefined;
  /** Controlled selected value(s). string|null for single mode, readonly string[] for multiple. */
  value?: string | null;
  /** Initial selected value(s) for uncontrolled mode. */
  defaultValue?: string | null;
  /** Fired when the selected value(s) change. */
  onChange?: (value: string | null) => void;
}

/** Props for toggle group in multiple-selection mode. */
interface ToggleGroupMultipleProps {
  /**
   * Switches between radio-style single selection and pressed-button-style multiple selection.
   * Switches value/onChange/defaultValue from string|null to readonly string[].
   */
  selectionMode: "multiple";
  /** Controlled selected value(s). string|null for single mode, readonly string[] for multiple. */
  value?: readonly string[];
  /** Initial selected value(s) for uncontrolled mode. */
  defaultValue?: readonly string[];
  /** Fired when the selected value(s) change. */
  onChange?: (value: readonly string[]) => void;
}

/** Props for toggle group base. */
interface ToggleGroupBaseProps {
  /** Single mode only. When true, clicking the active item deselects it (allowing a null value). */
  allowDeselect?: boolean;
  /** Disables the entire group. */
  disabled?: boolean;
  /** Item size token. */
  size?: SegmentedSize;
  /** Visual style variant. */
  variant?: SegmentedVariant;
  /** Layout axis and arrow-key navigation direction. */
  orientation?: "horizontal" | "vertical";
  /** When true, arrow navigation wraps and horizontal items flex-wrap. */
  wrap?: boolean;
  /** Controlled highlighted (focused) value for cross-component navigation. */
  highlighted?: string | null;
  /** Fired when the highlighted value changes. */
  onHighlightChange?: (value: string | null) => void;
  /** Fired when arrow navigation reaches the first/last item with wrap disabled. */
  onNavigationBoundaryReached?: (
    direction: "previous" | "next",
    event: globalThis.KeyboardEvent,
    key: string,
  ) => void;
  /** Called when key down occurs. */
  onKeyDown?: (event: ReactKeyboardEvent) => void;
  /** Accessible name for the group container. */
  label?: string;
  /** ID of the element labelling the group. */
  "aria-labelledby"?: string;
  /** Single mode only. Form field name; renders a hidden input for native form submission. */
  name?: string;
  /** Additional class names merged onto the rendered element. */
  className?: string;
  /** ToggleGroup.Item children. */
  children: ReactNode;
  /** Ref forwarded to the underlying element. */
  ref?: Ref<HTMLDivElement>;
}

/** Props for toggle group. */
export type ToggleGroupProps = ToggleGroupBaseProps &
  (ToggleGroupSingleProps | ToggleGroupMultipleProps);

interface ToggleGroupSeedElementProps {
  children?: ReactNode;
  value?: string;
  disabled?: boolean;
  hidden?: boolean;
  inert?: boolean;
  "aria-hidden"?: boolean | "true" | "false";
}

function collectEnabledToggleValues(children: ReactNode, skippedAncestor = false): string[] {
  const enabledValues: string[] = [];

  Children.forEach(children, (child) => {
    if (!isValidElement<ToggleGroupSeedElementProps>(child)) return;
    if (child.type === ToggleGroup) return;

    const skipped = skippedAncestor || isSeedElementSkipped(child.props);
    if (child.type === ToggleGroupItem && typeof child.props.value === "string") {
      if (!child.props.disabled && !skipped) enabledValues.push(child.props.value);
      return;
    }

    enabledValues.push(...collectEnabledToggleValues(child.props.children, skipped));
  });

  return enabledValues;
}

/** Compound toggle button group with keyboard navigation for single or multiple selection. */
export function ToggleGroup(props: ToggleGroupProps) {
  const {
    allowDeselect = false,
    disabled = false,
    size = "sm",
    variant = "default",
    orientation = "horizontal",
    wrap = true,
    highlighted: controlledHighlighted,
    onHighlightChange,
    onNavigationBoundaryReached,
    onKeyDown,
    label,
    "aria-labelledby": ariaLabelledBy,
    name,
    className,
    children,
    ref,
  } = props;
  const selectionMode: ToggleGroupSelectionMode = props.selectionMode ?? "single";

  const containerRef = useRef<HTMLDivElement>(null);
  const composedRef = useComposedRefs(containerRef, ref);
  const { items, registeredItems, registerItem, unregisterItem } =
    useSelectableCollection(containerRef);
  const [hasLiveRegistrations, setHasLiveRegistrations] = useState(false);
  const registerLiveItem = useCallback(
    (itemId: string, itemValue: string, itemDisabled: boolean, element: HTMLElement | null) => {
      setHasLiveRegistrations(true);
      registerItem(itemId, itemValue, itemDisabled, element);
    },
    [registerItem],
  );

  const singleProps = selectionMode === "single" ? (props as ToggleGroupSingleProps) : null;
  const multipleProps = selectionMode === "multiple" ? (props as ToggleGroupMultipleProps) : null;

  const isValueControlled = "value" in props;
  const [singleValue, setSingleValue, , resetSingleValue] = useControllableState<string | null>(
    isValueControlled
      ? {
          controlled: true,
          value: singleProps?.value ?? null,
          defaultValue: singleProps?.defaultValue ?? null,
          onChange: singleProps?.onChange,
        }
      : {
          defaultValue: singleProps?.defaultValue ?? null,
          onChange: singleProps?.onChange,
        },
  );
  const invalidatePendingSingleReset = useFormReset(
    containerRef,
    singleProps?.defaultValue ?? null,
    resetSingleValue,
    !isValueControlled && selectionMode === "single",
  );

  const [multipleValue, setMultipleValue, , resetMultipleValue] = useControllableState<
    readonly string[]
  >(
    isValueControlled
      ? {
          controlled: true,
          value: multipleProps?.value ?? EMPTY_VALUES,
          defaultValue: multipleProps?.defaultValue ?? EMPTY_VALUES,
          onChange: multipleProps?.onChange,
        }
      : {
          defaultValue: multipleProps?.defaultValue ?? EMPTY_VALUES,
          onChange: multipleProps?.onChange,
        },
  );
  const invalidatePendingMultipleReset = useFormReset(
    containerRef,
    multipleProps?.defaultValue ?? EMPTY_VALUES,
    resetMultipleValue,
    !isValueControlled && selectionMode === "multiple",
  );

  const [highlightedValue, setHighlightedValue] = useControllableState<string | null>(
    "highlighted" in props
      ? {
          controlled: true,
          value: controlledHighlighted ?? null,
          defaultValue: null,
          onChange: onHighlightChange,
        }
      : {
          defaultValue: null,
          onChange: onHighlightChange,
        },
  );

  const usesButtonSemantics = selectionMode === "multiple" || allowDeselect;

  const isItemSelected = useCallback(
    (value: string): boolean => {
      if (selectionMode === "multiple") {
        return multipleValue.includes(value);
      }
      return singleValue === value;
    },
    [selectionMode, multipleValue, singleValue],
  );

  const handleValueChange = useCallback(
    (newValue: string | null) => {
      if (newValue === null) return;
      if (selectionMode === "multiple") {
        invalidatePendingMultipleReset();
        setMultipleValue((prev) =>
          prev.includes(newValue) ? prev.filter((v) => v !== newValue) : [...prev, newValue],
        );
        return;
      }
      invalidatePendingSingleReset();
      setSingleValue((prev) => (prev === newValue && allowDeselect ? null : newValue));
    },
    [
      allowDeselect,
      invalidatePendingMultipleReset,
      invalidatePendingSingleReset,
      selectionMode,
      setMultipleValue,
      setSingleValue,
    ],
  );

  const enabledItems = getEnabledSelectableCollectionItems(items, disabled);
  const seededEnabledValues = disabled ? [] : collectEnabledToggleValues(children);
  const enabledValues = hasLiveRegistrations
    ? enabledItems.map((item) => item.value)
    : seededEnabledValues;
  const activeHighlightedValue =
    highlightedValue !== null && enabledValues.includes(highlightedValue) ? highlightedValue : null;
  const selectedAnchor = selectionMode === "single" ? singleValue : null;
  const tabTargetValue =
    [highlightedValue, selectedAnchor].find(
      (candidate): candidate is string => candidate !== null && enabledValues.includes(candidate),
    ) ??
    enabledValues[0] ??
    null;

  const { onKeyDown: navKeyDown } = useNavigation({
    containerRef,
    role: usesButtonSemantics ? "button" : "radio",
    orientation,
    wrap,
    moveFocus: true,
    upKeys: ["ArrowUp", "ArrowLeft"],
    downKeys: ["ArrowDown", "ArrowRight"],
    highlighted: tabTargetValue,
    enabled: !disabled,
    onHighlightChange: usesButtonSemantics ? setHighlightedValue : handleValueChange,
    onNavigationBoundaryReached,
    scopeToContainer: true,
    ownerSelector: usesButtonSemantics ? '[data-diffgazer-selectable-owner="toggle"]' : undefined,
  });

  const handleKeyDown = (e: ReactKeyboardEvent) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    navKeyDown(e);
  };

  const contextValue = useMemo(
    () => ({
      isItemSelected,
      onChange: handleValueChange,
      onHighlightChange: setHighlightedValue,
      disabled,
      size,
      variant,
      highlightedValue: activeHighlightedValue,
      usesButtonSemantics,
      tabTargetValue,
      registerItem: registerLiveItem,
      unregisterItem,
    }),
    [
      isItemSelected,
      handleValueChange,
      setHighlightedValue,
      disabled,
      size,
      variant,
      activeHighlightedValue,
      usesButtonSemantics,
      tabTargetValue,
      registerLiveItem,
      unregisterItem,
    ],
  );

  // Pill variant: a single absolutely-positioned indicator tracks the active
  // item's rect. The hook is null-fed for `selectionMode="multiple"` (which
  // uses button semantics with no single-active concept) and when the variant
  // doesn't use a pill indicator, so the observer is never created.
  const usesWrappedPillLayout = variant === "pill" && orientation === "horizontal" && wrap;
  const pillTargetValue =
    variant === "pill" && selectionMode === "single" && !usesWrappedPillLayout ? singleValue : null;
  const pillRect = useFloatingIndicator(containerRef, pillTargetValue);

  const underlineTargetValue =
    variant === "underline" && selectionMode === "single" ? singleValue : null;
  const underlineRect = useFloatingIndicator(containerRef, underlineTargetValue);

  const hiddenInputValue = selectionMode === "single" && name ? singleValue : null;
  const selectedItem = registeredItems.find((item) => item.value === hiddenInputValue);
  const isHiddenInputDisabled =
    disabled ||
    (hasLiveRegistrations
      ? selectedItem === undefined ||
        selectedItem.disabled ||
        selectedItem.element?.matches(":disabled") === true
      : !seededEnabledValues.includes(hiddenInputValue ?? ""));

  return (
    <ToggleGroupContext value={contextValue}>
      {/* biome-ignore lint/a11y/noStaticElementInteractions: role is dynamically "group"/"radiogroup" and the container owns roving keyboard handling for its items; Biome cannot resolve the dynamic role. */}
      {/* biome-ignore lint/a11y/useAriaPropsSupportedByRole: the aria props apply to the dynamic group/radiogroup role, which Biome cannot statically resolve. */}
      <div
        ref={composedRef}
        role={usesButtonSemantics ? "group" : "radiogroup"}
        data-diffgazer-selectable-owner={usesButtonSemantics ? "toggle" : "radio"}
        data-variant={variant}
        data-orientation={orientation}
        aria-label={label}
        aria-labelledby={ariaLabelledBy}
        aria-orientation={usesButtonSemantics ? undefined : orientation}
        aria-disabled={disabled || undefined}
        onKeyDown={handleKeyDown}
        className={cn(
          segmentedContainerVariants({ variant, orientation }),
          "w-fit max-w-full",
          wrap && orientation === "horizontal" && "flex-wrap",
          usesWrappedPillLayout && "gap-1 [&>[data-state=on]]:bg-primary",
          className,
        )}
      >
        {!usesWrappedPillLayout && variant === "pill" && pillRect && (
          <span
            aria-hidden="true"
            data-slot="toggle-group-pill"
            className={segmentedPillIndicatorClass}
            style={{ left: pillRect.left, width: pillRect.width }}
          />
        )}
        {variant === "underline" && underlineRect && (
          <span
            aria-hidden="true"
            data-slot="toggle-group-underline"
            className={segmentedUnderlineIndicatorClass}
            style={
              orientation === "vertical"
                ? { top: underlineRect.top, height: underlineRect.height, right: 0, width: 1 }
                : { left: underlineRect.left, width: underlineRect.width, bottom: 0, height: 1 }
            }
          />
        )}
        {hiddenInputValue != null && (
          <input
            type="hidden"
            name={name}
            value={hiddenInputValue}
            disabled={isHiddenInputDisabled}
          />
        )}
        {children}
      </div>
    </ToggleGroupContext>
  );
}

"use client";

import { createContext, useContext } from "react";
import type { SegmentedSize, SegmentedVariant } from "@/lib/segmented-variants";

export type ToggleGroupSelectionMode = "single" | "multiple";

/** Context value shared by toggle group. */
export interface ToggleGroupContextValue {
  /** Returns whether the given item value is selected. */
  isItemSelected: (value: string) => boolean;
  /** Fired when the selected value(s) change. */
  onChange: (value: string) => void;
  /** Fired when the highlighted value changes. */
  onHighlightChange: (value: string | null) => void;
  /** Disables the entire group. */
  disabled: boolean;
  /** Item size token. */
  size: SegmentedSize;
  /** Visual style variant. */
  variant: SegmentedVariant;
  highlightedValue: string | null;
  usesButtonSemantics: boolean;
  tabTargetValue: string | null;
  /** Registers item with toggle group. */
  registerItem: (
    itemId: string,
    value: string,
    disabled: boolean,
    element: HTMLElement | null,
  ) => void;
  /** Unregisters item from toggle group. */
  unregisterItem: (itemId: string) => void;
}

export const ToggleGroupContext = createContext<ToggleGroupContextValue | undefined>(undefined);

export function useToggleGroupContext() {
  const context = useContext(ToggleGroupContext);
  if (!context) {
    throw new Error("ToggleGroup.Item must be used within ToggleGroup");
  }
  return context;
}

"use client";

import {
  type ComponentPropsWithRef,
  type FocusEvent,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  useId,
  useLayoutEffect,
  useRef,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { BracketMarkers } from "@/lib/segmented-brackets";
import { segmentedItemVariants } from "@/lib/segmented-variants";
import { cn } from "@/lib/utils";
import { useToggleGroupContext } from "./toggle-group-context";

/** Props for toggle group item. */
export interface ToggleGroupItemProps
  extends Omit<ComponentPropsWithRef<"button">, "children" | "disabled" | "value"> {
  /** Stable identifier matched against the group value. */
  value: string;
  /** Optional trailing count rendered as [label count]. */
  count?: number;
  /** Disables this item only; removed from arrow navigation and focus. */
  disabled?: boolean;
  /** Item label. */
  children: ReactNode;
}

export function ToggleGroupItem({
  value,
  count,
  disabled,
  className,
  children,
  ref,
  onClick,
  onKeyDown,
  onMouseEnter,
  onFocus,
  ...props
}: ToggleGroupItemProps) {
  const context = useToggleGroupContext();
  const itemId = useId();
  const rootRef = useRef<HTMLButtonElement>(null);
  const composedRef = useComposedRefs(rootRef, ref);
  const isActive = context.isItemSelected(value);
  const isHighlighted = context.highlightedValue === value;
  const isDisabled = context.disabled || !!disabled;
  const isTabTarget = !isDisabled && context.tabTargetValue === value;
  const { registerItem, unregisterItem, variant } = context;

  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
    onClick?.(event);
    if (!event.defaultPrevented && !isDisabled) context.onChange(value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    onKeyDown?.(event);
    if (
      !event.defaultPrevented &&
      context.usesButtonSemantics &&
      !isDisabled &&
      (event.key === "Enter" || event.key === " ")
    ) {
      event.preventDefault();
      context.onChange(value);
    }
  };

  const handleFocus = (event: FocusEvent<HTMLButtonElement>) => {
    onFocus?.(event);
    if (!event.defaultPrevented) context.onHighlightChange(value);
  };

  useLayoutEffect(() => {
    registerItem(itemId, value, disabled === true, rootRef.current);
    return () => unregisterItem(itemId);
  }, [registerItem, unregisterItem, itemId, value, disabled]);

  // BracketMarkers apply to the bracket variant regardless of `count`. The
  // count renders as a separate styled span after the label, so the brackets
  // only ever wrap the actual children — never the count.
  const renderedChildren =
    variant === "bracket" ? <BracketMarkers state="on">{children}</BracketMarkers> : children;

  return (
    // biome-ignore lint/a11y/useAriaPropsSupportedByRole: role is conditionally "radio" (Biome cannot resolve the ternary); aria-checked is applied only in the radio branch and aria-pressed only in the button branch.
    <button
      {...props}
      ref={composedRef}
      type="button"
      role={context.usesButtonSemantics ? undefined : "radio"}
      data-value={value}
      data-diffgazer-navigation-item={context.usesButtonSemantics ? "button" : "radio"}
      data-state={isActive ? "on" : "off"}
      data-highlighted={isHighlighted ? "" : undefined}
      aria-checked={context.usesButtonSemantics ? undefined : isActive}
      aria-pressed={context.usesButtonSemantics ? isActive : undefined}
      aria-disabled={isDisabled || undefined}
      disabled={isDisabled}
      tabIndex={isTabTarget ? 0 : -1}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onMouseEnter={onMouseEnter}
      onFocus={handleFocus}
      className={cn(
        // group/segmented-item lets the bracket markers (and any future
        // decoration) react to data-state without a separate context read.
        "group/segmented-item",
        segmentedItemVariants({
          variant,
          size: context.size,
          highlighted: (isHighlighted && !isActive) || undefined,
        }),
        className,
      )}
    >
      {renderedChildren}
      {/* The item is a flex container, so a whitespace text node between the
          label and the count is not rendered; it only keeps the accessible name
          as "Error 3". The visible gutter is a margin, and tabular-nums keeps
          multi-digit counts on one column. */}
      {count != null && (
        <>
          {" "}
          <span data-slot="toggle-group-count" className="ml-1.5 tabular-nums opacity-70">
            {count}
          </span>
        </>
      )}
    </button>
  );
}

"use client";

import type { ReactElement, Ref } from "react";
import {
  ToggleGroup as ToggleGroupRoot,
  type ToggleGroupProps as ToggleGroupRootProps,
} from "./toggle-group";
import { ToggleGroupItem, type ToggleGroupItemProps } from "./toggle-group-item";

type ToggleGroupSingleBoundProps<TValue extends string> = Omit<
  Extract<ToggleGroupRootProps, { selectionMode?: "single" | undefined }>,
  "value" | "defaultValue" | "onChange" | "highlighted" | "onHighlightChange"
> & {
  value?: TValue | null;
  defaultValue?: TValue | null;
  onChange?: (value: TValue | null) => void;
  highlighted?: TValue | null;
  onHighlightChange?: (value: TValue | null) => void;
  ref?: Ref<HTMLDivElement>;
};

type ToggleGroupMultipleBoundProps<TValue extends string> = Omit<
  Extract<ToggleGroupRootProps, { selectionMode: "multiple" }>,
  "value" | "defaultValue" | "onChange" | "highlighted" | "onHighlightChange"
> & {
  value?: readonly TValue[];
  defaultValue?: readonly TValue[];
  onChange?: (value: readonly TValue[]) => void;
  highlighted?: TValue | null;
  onHighlightChange?: (value: TValue | null) => void;
  ref?: Ref<HTMLDivElement>;
};

type ToggleGroupBoundProps<TValue extends string> =
  | ToggleGroupSingleBoundProps<TValue>
  | ToggleGroupMultipleBoundProps<TValue>;

type ToggleGroupItemBoundProps<TValue extends string> = Omit<ToggleGroupItemProps, "value"> & {
  value: TValue;
};

export type CreateToggleGroupReturn<T extends readonly string[]> = {
  readonly values: T;
  (props: ToggleGroupBoundProps<T[number]>): ReactElement;
  Item: (props: ToggleGroupItemBoundProps<T[number]>) => ReactElement;
};

/**
 * Binds ToggleGroup and ToggleGroup.Item to one authoritative value collection so
 * item values and consumer callbacks share the same literal union.
 */
export function createToggleGroup<const T extends readonly string[]>(
  values: T,
): CreateToggleGroupReturn<T> {
  type TValue = T[number];

  function BoundToggleGroup(props: ToggleGroupBoundProps<TValue>) {
    if (props.selectionMode === "multiple") {
      const { onChange, onHighlightChange, ...rest } = props;
      return (
        <ToggleGroupRoot
          {...rest}
          selectionMode="multiple"
          onChange={onChange ? (value) => onChange(value as readonly TValue[]) : undefined}
          onHighlightChange={
            onHighlightChange ? (value) => onHighlightChange(value as TValue | null) : undefined
          }
        />
      );
    }

    const { onChange, onHighlightChange, ...rest } = props;
    return (
      <ToggleGroupRoot
        {...rest}
        onChange={onChange ? (value) => onChange(value as TValue | null) : undefined}
        onHighlightChange={
          onHighlightChange ? (value) => onHighlightChange(value as TValue | null) : undefined
        }
      />
    );
  }

  return Object.assign(BoundToggleGroup, {
    Item: ToggleGroupItem,
    values,
  });
}
